window.dccClientAdmin=render;window.dccLegacyDelete=async id=>{const cl=c(id);if(!cl)return;if(!confirm('¿Eliminar definitivamente a '+cl.name+'?'))return;try{if(!window.supabaseClient)throw new Error('Sin conexión con Supabase');try{await supabaseClient.from('dietas').delete().eq('client_id',id)}catch(e){}const {data:deleted,error}=await supabaseClient.from('clients').delete().eq('id',id).select('id');if(error)throw error;if(!Array.isArray(deleted)||!deleted.length)throw new Error('El servidor no confirmó la eliminación');data.clients=(data.clients||[]).filter(x=>String(x.id)!==String(id));['checkins','diets','routines','weights','workoutHistory','bodyFatHistory','messages','notificationState'].forEach(k=>{if(data[k]&&typeof data[k]==='object')delete data[k][id]});if(typeof saveData==='function')saveData();if(typeof showCoach==='function')showCoach('clients');if(typeof toast==='function')toast('Cliente eliminado definitivamente')}catch(e){console.error('Error eliminando cliente:',e);if(typeof toast==='function')toast('No se pudo eliminar el cliente');else alert('No se pudo eliminar el cliente')}};function install(){const old=window.openClient;if(typeof old==='function'&&old.__dccClientAdminPremium)return;const fn=id=>render(id,'summary');fn.__dccAdmin=true;fn.__dccClientAdminPremium=true;fn.__legacy=old;window.openClient=fn;window.showClientAdmin=fn}install();if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',install,{once:true});
